function curatePool(address token) external {
    require(iPOOLS(POOLS).isAsset(token) || iPOOLS(POOLS).isAnchor(token));
    if(!isCurated(token)){
        if(curatedPoolCount < curatedPoolLimit){ // Limit
            _isCurated[token] = true;
            curatedPoolCount += 1;
        }
    }
    emit Curated(msg.sender, token);
}

